/* SDK8/9 typed volume storage,view andsampling acceptance. */
typedef struct TCContext{TCDevice*d;HMODULE module;UINT mode;BOOL core;}TCContext;
static HRESULT tc_create(TCContext*,UINT,UINT,UINT,UINT,DWORD,UINT,UINT,TCTexture**);
static void tc_size(TCContext*,TCView*,UINT);
static void tc_sampler(TCContext*);
static HRESULT tc_fvf(TCDevice*);
static HRESULT tc_bind(TCContext*,TCTexture*);
static void tc_read(TCContext*);
static HRESULT tc_reset(TCContext*);
static void tc_check(BOOL ok,const char*s){if(!ok){tc_report(s);ExitProcess(1);}}
static void tc_expect(HRESULT hr,const char*s){tc_check(SUCCEEDED(hr),s);}
static void tc_metadata(TCContext*c,TCTexture*t,UINT level,UINT format,UINT width,UINT height,UINT depth,UINT bytes){TCView*v=NULL,*again=NULL;tc_expect(TC_VIEW(t,level,&v),"FAIL volume level view");tc_expect(TC_VIEW(t,level,&again),"FAIL repeated volume view");tc_check(v==again,"FAIL volume identity");TCDevice*parent=NULL;tc_expect(TC_VPARENT(v,&parent),"FAIL volume parent");tc_check(parent==c->d,"FAIL volume device identity");TC_DREL(parent);TCVolumeDesc desc;tc_expect(TC_VDESC(v,&desc),"FAIL volume descriptor");tc_check(desc.Format==format&&desc.Type==2&&desc.Width==width&&desc.Height==height&&desc.Depth==depth,"FAIL volume fields");tc_size(c,v,bytes);TC_VREL(again);TC_VREL(v);}
static void tc_capture(TCContext*c,UINT step,UINT slice){const float xy[6][2]={{-.5f,-.5f},{7.5f,-.5f},{-.5f,7.5f},{-.5f,7.5f},{7.5f,-.5f},{7.5f,7.5f}};struct TVertex{float x,y,z,w;DWORD color;float u,v,t;};struct TVertex vertices[6];for(UINT n=0;n<6;n++)vertices[n]=(struct TVertex){xy[n][0],xy[n][1],.5f,1,0xffffffff,.5f,.5f,(slice+.5f)/4.0f};tc_expect(TC_CLEAR(c->d,0,NULL,1,0xff010203,1,0),"FAIL volume clear");tc_expect(TC_BEGIN(c->d),"FAIL volume scene");tc_expect(TC_DRAW(c->d,D3DPT_TRIANGLELIST,2,vertices,sizeof(vertices[0])),"FAIL volume sample");tc_expect(TC_END(c->d),"FAIL volume end scene");tc_read(c);char line[160];wsprintfA(line,"VOLCORE FRAME index=%u mode=%u step=%u slice=%u readback=1",tc_frame_index++,c->mode,step,slice);tc_report(line);}
static void tc_cases(TCContext*c){
 tc_expect(TC_RS(c->d,D3DRS_ZENABLE,FALSE),"FAIL volume Z");tc_expect(TC_RS(c->d,D3DRS_LIGHTING,FALSE),"FAIL volume lighting");tc_expect(TC_RS(c->d,D3DRS_CULLMODE,D3DCULL_NONE),"FAIL volume cull");tc_expect(tc_fvf(c->d),"FAIL volume FVF");tc_expect(TC_TSS(c->d,0,D3DTSS_COLOROP,D3DTOP_SELECTARG1),"FAIL volume op");tc_expect(TC_TSS(c->d,0,D3DTSS_COLORARG1,D3DTA_TEXTURE),"FAIL volume argument");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAOP,D3DTOP_SELECTARG1),"FAIL volume alpha");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAARG1,D3DTA_TEXTURE),"FAIL volume alpha argument");tc_sampler(c);
 UINT invalid=0;if(c->mode!=2){for(UINT n=0;n<13;n++){UINT w=n==0?0:n==1?2049:4,h=n==2?0:n==3?2049:4,depth=n==4?0:n==5?2049:4,levels=n==6?99:1,usage=n==7?1:n==8?2:0,format=n==10?113:n==11?827611204u:21,pool=n==9?4:0;TCTexture*out=(void*)99;tc_check(tc_create(c,w,h,depth,levels,usage,format,pool,n==12?NULL:&out)==D3DERR_INVALIDCALL&&(n==12?out==(void*)99:out==NULL),"FAIL API8 volume invalid/output");invalid++;}}
 TCTexture*t=NULL;D3DLOCKED_BOX lock;
 if(c->mode==2){t=(void*)99;tc_check(tc_create(c,3,2,3,0,0,65,1,&t)==D3DERR_INVALIDCALL&&t==NULL,"FAIL ordinary9 volume65 refusal");}else{
  tc_expect(tc_create(c,3,2,3,0,0,65,1,&t),"FAIL API8 volume65 create");tc_check(TC_LEVELS(t)==2,"FAIL volume65 mip count");for(UINT l=0;l<2;l++){UINT w=l?1:3,h=l?1:2,depth=l?1:3;tc_metadata(c,t,l,65,w,h,depth,w*h*depth*4);tc_expect(TC_LOCK(t,l,&lock,NULL,0),"FAIL volume65 lock");tc_check(lock.RowPitch==(INT)(w*4)&&lock.SlicePitch==(INT)(w*h*4),"FAIL volume65 row/slice pitch");for(UINT z=0;z<depth;z++)for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++){DWORD*p=(DWORD*)((BYTE*)lock.pBits+z*lock.SlicePitch+y*lock.RowPitch);tc_check(!p[x],"FAIL volume65 initial zero");p[x]=0x12000000u|(l<<16)|(z<<12)|(y<<8)|x;}tc_expect(TC_UNLOCK(t,l),"FAIL volume65 upload");tc_expect(TC_LOCK(t,l,&lock,NULL,16),"FAIL volume65 readonly");for(UINT z=0;z<depth;z++)for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++)tc_check(((DWORD*)((BYTE*)lock.pBits+z*lock.SlicePitch+y*lock.RowPitch))[x]==(0x12000000u|(l<<16)|(z<<12)|(y<<8)|x),"FAIL volume65 preserved bits");tc_expect(TC_UNLOCK(t,l),"FAIL volume65 readonly unlock");}tc_check(!TC_TREL(t),"FAIL volume65 refs");}
 const DWORD colors[4]={0xffb02010,0xff20a040,0xff1040c0,0xffc0a020};tc_expect(tc_create(c,4,4,4,0,0,21,1,&t),"FAIL main volume create");tc_check(TC_LEVELS(t)==3,"FAIL main volume full mip count");for(UINT l=0;l<3;l++){UINT w=4u>>l;tc_metadata(c,t,l,21,w,w,w,w*w*w*4);tc_expect(TC_LOCK(t,l,&lock,NULL,0),"FAIL main volume mip lock");tc_check(lock.RowPitch==(INT)(w*4)&&lock.SlicePitch==(INT)(w*w*4),"FAIL main volume pitch");for(UINT z=0;z<w;z++)for(UINT y=0;y<w;y++)for(UINT x=0;x<w;x++){DWORD*p=(DWORD*)((BYTE*)lock.pBits+z*lock.SlicePitch+y*lock.RowPitch);tc_check(!p[x],"FAIL main volume zero");p[x]=colors[z]^(l*0x00080808);}tc_expect(TC_UNLOCK(t,l),"FAIL main volume upload");}
 tc_expect(tc_bind(c,t),"FAIL main volume bind");for(UINT slice=0;slice<4;slice++)tc_capture(c,slice,slice);
 TCView*v=NULL;tc_expect(TC_VIEW(t,0,&v),"FAIL volume child edit");D3DBOX box={1,1,3,3,1,2};tc_expect(TC_VLOCK(v,&lock,&box,0),"FAIL volume child lock");tc_check(lock.RowPitch==16&&lock.SlicePitch==64,"FAIL volume child whole row/slice pitch");for(UINT y=0;y<2;y++)for(UINT x=0;x<2;x++)((DWORD*)((BYTE*)lock.pBits+y*lock.RowPitch))[x]=0xffd06020;tc_expect(TC_VUNLOCK(v),"FAIL volume child upload");TC_VREL(v);tc_capture(c,4,1);tc_capture(c,5,2);tc_expect(tc_bind(c,NULL),"FAIL main volume unbind");tc_check(!TC_TREL(t),"FAIL main volume refs");
 tc_expect(tc_reset(c),"FAIL volume Reset");char line[220];wsprintfA(line,"VOLCORE CHECK mode=%u invalidCases=%u cpu65=%u slices=4 mipLevels=3 partialRowPitch=16 partialSlicePitch=64 viewIdentity=1 reset=1 finalRefs=0",c->mode,invalid,c->mode!=2);tc_report(line);
}
